	@ParameterizedTest
	@ValueSource(strings = { "TRUNCATED", "TRAILING", "NONCANONICAL", "WRONG_TYPE", "OVERFLOW", "INLINE" })
	void revisionBoundaryRejectsMalformedUnusedTailWithoutMutation(String corruption) throws Exception {
		try (ClosingValueStore store = new ClosingValueStore(directory.resolve("values").toFile(),
				new LmdbStoreConfig())) {
			store.startTransaction(true);
			store.storeValue(SimpleValueFactory.getInstance().createBNode("revision-boundary-owner"));
			store.commit();
		}
		ByteBuffer bytes = ByteBuffer.allocate(32);
		if (corruption.equals("NONCANONICAL")) {
			bytes.put(new byte[] { (byte) 250, 0, 0, 1 });
		} else {
			Varint.writeUnsigned(bytes, corruption.equals("OVERFLOW") ? Long.MAX_VALUE : 1L);
		}
		if (!corruption.equals("TRUNCATED")) {
			bytes.put(corruption.equals("WRONG_TYPE") ? (byte) 6 : ValueStoreRecordCodec.ID_KEY);
			Varint.writeUnsigned(bytes, ValueIds.createId(corruption.equals("INLINE") ? ValueIds.T_INTEGER
					: ValueIds.T_BNODE, 1L));
		}
		if (corruption.equals("TRAILING")) {
			bytes.put((byte) 0);
		}
		byte[] key = Arrays.copyOf(bytes.array(), bytes.position());
		byte[] payload = new byte[0];
		LmdbCompatibilityFixtures.nativePut(directory, "unused_ids", key, payload);
		long before = LmdbCompatibilityFixtures.nativeTransactionId(directory);
		IOException failure = assertThrows(IOException.class, () -> {
			try (ClosingValueStore store = new ClosingValueStore(directory.resolve("values").toFile(),
					new LmdbStoreConfig())) {
				// An invalid persisted tail cannot supply the monotonic revision boundary for a writer.
			}
		});
		assertTrue(failure.getMessage().contains("revision boundary"), failure.getMessage());
		assertEquals(before, LmdbCompatibilityFixtures.nativeTransactionId(directory));
		assertArrayEquals(payload, LmdbCompatibilityFixtures.nativeGet(directory, "unused_ids", key));
	}

	@Test
	void revisionBoundaryPropagatesNativeTailReadErrorsWithoutMutation() throws Exception {
		try (ClosingValueStore store = new ClosingValueStore(directory.resolve("values").toFile(),
				new LmdbStoreConfig())) {
			store.startTransaction(true);
			store.storeValue(SimpleValueFactory.getInstance().createBNode("revision-read-error-owner"));
			store.commit();
		}
		long before = LmdbCompatibilityFixtures.nativeTransactionId(directory);
		AtomicInteger unused = new AtomicInteger(-1);
		AtomicLong unusedCursor = new AtomicLong();
		try (MockedStatic<LMDB> ignored = mockStatic(LMDB.class, invocation -> {
			String method = invocation.getMethod().getName();
			if (method.equals("mdb_dbi_open") && "unused_ids".equals(invocation.getArgument(1))) {
				Object result = invocation.callRealMethod();
				if (((Integer) result) == LMDB.MDB_SUCCESS) {
					IntBuffer handle = invocation.getArgument(3);
					unused.set(handle.get(handle.position()));
				}
				return result;
			}
			if (method.equals("mdb_cursor_open") && ((Integer) invocation.getArgument(1)) == unused.get()) {
				Object result = invocation.callRealMethod();
				PointerBuffer handle = invocation.getArgument(2);
				unusedCursor.set(handle.get(handle.position()));
				return result;
			}
			if (method.equals("mdb_cursor_get") && ((Long) invocation.getArgument(0)) == unusedCursor.get()
					&& ((Integer) invocation.getArgument(3)) == LMDB.MDB_LAST) {
				return LMDB.MDB_CORRUPTED;
			}
			return invocation.callRealMethod();
		})) {
			assertThrows(IOException.class, () -> {
				try (ClosingValueStore store = new ClosingValueStore(directory.resolve("values").toFile(),
						new LmdbStoreConfig())) {
					// A native tail error cannot be treated as an empty historical cohort tree.
				}
			});
		}
		assertEquals(before, LmdbCompatibilityFixtures.nativeTransactionId(directory));
	}

	@Test
	void committedDictionaryCrashSnapshotDoesNotReconstructCounts() throws Exception {
		Path live = directory.resolve("live/values");
		Path crashed = directory.resolve("crashed/values");
		var vf = SimpleValueFactory.getInstance();
		var shared = vf.createIRI("urn:authority:datatype");
		var value = vf.createLiteral("committed before process death", shared);
		long valueId;
		try (ClosingValueStore source = new ClosingValueStore(live.toFile(),
				new LmdbStoreConfig().setForceSync(true))) {
			source.startTransaction(true);
			valueId = source.storeValue(value);
			source.commit();
			// No writer runs while copying this committed native image. Omit close, just as a JVM crash does.
			Files.createDirectories(crashed);
			Files.copy(live.resolve("data.mdb"), crashed.resolve("data.mdb"));
			List<LmdbStartupDiagnostics.Operation> observed = new ArrayList<>();
			LmdbStartupDiagnostics.OBSERVER.set(observed::add);
			try (ClosingValueStore reopened = new ClosingValueStore(crashed.toFile(), new LmdbStoreConfig())) {
				assertEquals(valueId, reopened.getId(value));
				assertEquals(value, reopened.getValue(valueId));
				assertFalse(observed.contains(LmdbStartupDiagnostics.Operation.REFCOUNT_REBUILD),
						"a committed dictionary transaction must carry its own exact-count proof");
			} finally {
				LmdbStartupDiagnostics.OBSERVER.remove();
			}
		}
	}

	@Test
	void postReadyMaintenanceReclaimsOneBoundedPersistedUnusedBatch() throws Exception {
		// This case asserts the durable-policy foreground/post-ready maintenance boundary.
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc,ospc").setAsyncValueCleanup(false)
				.setForceSync(true)
				.setValueDBSize(64L * 1024 * 1024)
				.setSketchEstimatorEnabled(false)
				.setValueHashCacheEnabled(false);
		LmdbStore owner = new LmdbStore(directory.toFile(), config);
		owner.init();
		awaitPostReady(owner);
		owner.shutDown();
		StoreProperties properties = new StoreProperties(directory.toFile());
		properties.load();
		try (ClosingValueStore values = new ClosingValueStore(directory.resolve("values").toFile(), properties,
				config)) {
			List<Long> ids = new ArrayList<>();
			values.startTransaction(true);
			for (int i = 0; i < 5000; i++) {
				ids.add(values.storeValue(SimpleValueFactory.getInstance().createLiteral("persisted-unused-" + i)));
			}
			values.commit();
			values.startTransaction(true);
			values.gcIds(ids, new HashSet<>());
			values.commit();
			assertTrue(values.hasTrustedReferenceCounts());
			assertEquals(5000L, values.getLmdbStats().get("unused_ids").entries());
		}
		assertEquals(5000L, LmdbCompatibilityFixtures.nativeValueEntryCount(directory, "unused_ids"));
		LmdbStore reopened = new LmdbStore(directory.toFile(), config);
		reopened.init();
		try {
			awaitPostReady(reopened);
			long remaining = reopened.getBackingStore().valueStore().getLmdbStats().get("unused_ids").entries();
			assertTrue(remaining < 5000L, "eligible persisted unused owners must receive a post-ready reclaim batch");
			assertTrue(remaining > 0L, "one post-ready batch must leave the rest of the durable backlog pending");
			assertTrue(reopened.getStartupStatus().retainedValueMaintenance());
		} finally {
			reopened.shutDown();
		}
	}

	@Test
	void persistedUnusedBatchCountsUncertainKeysAndRetainsTheirHints() throws Exception {
		seedUnusedDictionaryOwners(80);
		AtomicInteger checked = new AtomicInteger();
		try (ClosingValueStore store = new ClosingValueStore(directory.resolve("values").toFile(),
				new LmdbStoreConfig())) {
			store.completeStoreInitialization(ids -> {
				checked.addAndGet(ids.size());
				ids.clear();
			});
			store.reserveWriteCapacity(store.estimatePersistedUnusedBatchWriteBytes(17));
			assertEquals(17, store.reclaimPersistedUnusedIdsBatch(17));
			assertEquals(17, checked.get(), "uncertain liveness consumes the visited-key budget too");
			assertEquals(80L, store.getLmdbStats().get("unused_ids").entries());
			assertTrue(store.hasDeferredValueMaintenance());
		}
	}

