	@Test
	void failedPersistedUnusedBatchRollsBackEveryPayloadAndQueueDeletion() throws Exception {
		List<Long> owners = seedUnusedDictionaryOwners(80);
		AtomicInteger mainDbi = new AtomicInteger(-1);
		AtomicInteger deleted = new AtomicInteger();
		AtomicBoolean inject = new AtomicBoolean();
		try (MockedStatic<LMDB> ignored = mockStatic(LMDB.class, invocation -> {
			String method = invocation.getMethod().getName();
			if (method.equals("mdb_dbi_open") && invocation.getArgument(1) == null) {
				Object result = invocation.callRealMethod();
				if (((Integer) result) == LMDB.MDB_SUCCESS) {
					IntBuffer handle = invocation.getArgument(3);
					mainDbi.set(handle.get(handle.position()));
				}
				return result;
			}
			if (inject.get() && method.equals("mdb_del") && ((Integer) invocation.getArgument(1)) == mainDbi.get()
					&& deleted.incrementAndGet() == 4) {
				return LMDB.MDB_CORRUPTED;
			}
			return invocation.callRealMethod();
		});
				ClosingValueStore store = new ClosingValueStore(directory.resolve("values").toFile(),
						new LmdbStoreConfig())) {
			store.completeStoreInitialization(ids -> {
			});
			store.reserveWriteCapacity(store.estimatePersistedUnusedBatchWriteBytes(20));
			inject.set(true);
			try {
				assertThrows(IOException.class, () -> store.reclaimPersistedUnusedIdsBatch(20));
			} finally {
				inject.set(false);
			}
			assertEquals(4, deleted.get(), "the failure must follow three real pending payload deletions");
			assertEquals(80L, store.getLmdbStats().get("unused_ids").entries());
			assertEquals(0L, store.getLmdbStats().get("free_ids").entries());
			for (long id : owners) {
				assertTrue(store.getValue(id) != null, "aborted reclamation must retain payload " + id);
			}
		}
	}

	@Test
	void unknownUnusedBatchRetainsEveryOwnerWithoutConsultingLivenessOrCounts() throws Exception {
		List<Long> owners = seedUnusedDictionaryOwners(20);
		byte[] malformed = { (byte) 255 };
		LmdbCompatibilityFixtures.nativePut(directory, "ref_counts", ValueStoreRecordCodec.idKey(owners.getFirst()),
				malformed);
		try (ClosingValueStore store = new ClosingValueStore(directory.resolve("values").toFile(),
				new LmdbStoreConfig())) {
			assertFalse(store.hasTrustedReferenceCounts());
			store.completeStoreInitialization(ids -> {
				throw new AssertionError("UNKNOWN reclamation must not probe owners or liveness");
			});
			assertEquals(0L, store.estimatePersistedUnusedBatchWriteBytes(17));
			assertEquals(0, store.reclaimPersistedUnusedIdsBatch(17));
			assertEquals(20L, store.getLmdbStats().get("unused_ids").entries());
			assertEquals(0L, store.getLmdbStats().get("free_ids").entries());
		}
		assertArrayEquals(malformed,
				LmdbCompatibilityFixtures.nativeGet(directory, "ref_counts",
						ValueStoreRecordCodec.idKey(owners.getFirst())));
	}

	private List<Long> seedUnusedDictionaryOwners(int count) throws Exception {
		List<Long> owners = new ArrayList<>();
		try (ClosingValueStore store = new ClosingValueStore(directory.resolve("values").toFile(),
				new LmdbStoreConfig())) {
			store.startTransaction(true);
			for (int i = 0; i < count; i++) {
				owners.add(store.storeValue(SimpleValueFactory.getInstance().createLiteral("unused-owner-" + i)));
			}
			store.commit();
			store.startTransaction(true);
			store.gcIds(owners, new HashSet<>());
			store.commit();
		}
		return owners;
	}

	@Test
	void unknownCountsPermitWritesAndRetirementWithoutTouchingMalformedPayload() throws Exception {
		var vf = SimpleValueFactory.getInstance();
		var shared = vf.createIRI("urn:authority:datatype");
		var original = vf.createLiteral("original dependency owner", shared);
		long owner;
		long dependency;
		try (ClosingValueStore store = new ClosingValueStore(directory.resolve("values").toFile(),
				new LmdbStoreConfig())) {
			store.startTransaction(true);
			owner = store.storeValue(original);
			dependency = store.getId(shared);
			store.commit();
		}
		byte[] malformed = new byte[] { (byte) 0xff };
		LmdbCompatibilityFixtures.nativePut(directory, "ref_counts", LmdbCompatibilityFixtures.idKey(dependency),
				malformed);
		List<LmdbStartupDiagnostics.Operation> observed = new ArrayList<>();
		LmdbStartupDiagnostics.OBSERVER.set(observed::add);
		try (ClosingValueStore store = new ClosingValueStore(directory.resolve("values").toFile(),
				new LmdbStoreConfig())) {
			assertFalse(observed.contains(LmdbStartupDiagnostics.Operation.REFCOUNT_REBUILD),
					"untrusted startup must defer exhaustive reference-count verification");
			store.startTransaction(true);
			long added = store.storeValue(vf.createLiteral("new dependency owner", shared));
			Set<Long> next = new HashSet<>();
			store.gcIds(Set.of(owner, dependency), next);
			store.commit();
			assertEquals(owner, store.getId(original), "unknown counts retain every dictionary owner");
			assertEquals(dependency, store.getId(shared));
			assertEquals(vf.createLiteral("new dependency owner", shared), store.getValue(added));
			assertEquals(Set.of(), next);
		} finally {
			LmdbStartupDiagnostics.OBSERVER.remove();
		}
		assertArrayEquals(malformed, LmdbCompatibilityFixtures.nativeGet(directory, "ref_counts",
				LmdbCompatibilityFixtures.idKey(dependency)), "ordinary writes must bypass untrusted count records");
	}

