	@ParameterizedTest
	@ValueSource(strings = { "refcounts-generation", "refcounts-exact", "allocation-highwater" })
	void nativeAuthorityLookupErrorsAbortBeforeWritableBootstrap(String metadataKey) throws Exception {
		try (ClosingValueStore store = new ClosingValueStore(directory.resolve("values").toFile(),
				new LmdbStoreConfig())) {
			store.startTransaction(true);
			store.storeValue(SimpleValueFactory.getInstance().createBNode("lookup-error-owner"));
			store.commit();
		}
		if (metadataKey.equals("allocation-highwater")) {
			LmdbCompatibilityFixtures.nativePut(directory, "gc_meta", ReferenceCountProof.KEY, null);
		}
		long before = LmdbCompatibilityFixtures.nativeTransactionId(directory);
		byte[] injectedKey = metadataKey.getBytes(java.nio.charset.StandardCharsets.US_ASCII);
		try (MockedStatic<LMDB> ignored = mockStatic(LMDB.class, invocation -> {
			if (invocation.getMethod().getName().equals("mdb_get")) {
				MDBVal key = invocation.getArgument(2);
				if (key.mv_data().duplicate().equals(ByteBuffer.wrap(injectedKey))) {
					return LMDB.MDB_CORRUPTED;
				}
			}
			return invocation.callRealMethod();
		})) {
			assertThrows(IOException.class, () -> {
				try (ClosingValueStore store = new ClosingValueStore(directory.resolve("values").toFile(),
						new LmdbStoreConfig())) {
					// Admission must fail before any writable mutation can bless the damaged lookup as absence.
				}
			});
		}
		assertEquals(before, LmdbCompatibilityFixtures.nativeTransactionId(directory));
	}

