	@Test
	void exactProofBindsEveryAuthorityFieldAndChecksum() {
		byte[] generation = new byte[ReferenceCountProof.GENERATION_BYTES];
		generation[0] = 17;
		byte[] proof = ReferenceCountProof.encode(generation, 42L, 1001L);
		assertEquals(1001L, ReferenceCountProof.trustedNextId(ByteBuffer.wrap(proof), generation, 42L));
		for (int i = 0; i < proof.length; i++) {
			byte[] changed = proof.clone();
			changed[i] ^= 1;
			assertEquals(-1L, ReferenceCountProof.trustedNextId(ByteBuffer.wrap(changed), generation, 42L),
					"every schema, algorithm, generation, transaction, allocator and checksum byte is bound: " + i);
		}
		assertEquals(-1L, ReferenceCountProof.trustedNextId(ByteBuffer.wrap(proof), generation, 43L));
		generation[0]++;
		assertEquals(-1L, ReferenceCountProof.trustedNextId(ByteBuffer.wrap(proof), generation, 42L));
	}

	@Test
	void unknownCountsStayUnknownThroughWritesAndCloseUntilExplicitVerification() throws Exception {
		var vf = SimpleValueFactory.getInstance();
		var shared = vf.createIRI("urn:authority:explicit-datatype");
		try (ClosingValueStore store = new ClosingValueStore(directory.resolve("values").toFile(),
				new LmdbStoreConfig())) {
			store.startTransaction(true);
			store.storeValue(vf.createLiteral("before untrusted proof", shared));
			store.commit();
		}
		LmdbCompatibilityFixtures.nativePut(directory, "gc_meta", ReferenceCountProof.KEY, new byte[] { 0 });
		for (int reopen = 0; reopen < 2; reopen++) {
			try (ClosingValueStore store = new ClosingValueStore(directory.resolve("values").toFile(),
					new LmdbStoreConfig())) {
				assertFalse(store.hasTrustedReferenceCounts());
				assertTrue(store.isReferenceCountVerificationPending());
				store.startTransaction(true);
				store.storeValue(vf.createLiteral("after untrusted proof " + reopen, shared));
				store.commit();
				assertFalse(store.hasTrustedReferenceCounts());
			}
			assertNull(LmdbCompatibilityFixtures.nativeGet(directory, "gc_meta", ReferenceCountProof.KEY));
		}
		try (ClosingValueStore store = new ClosingValueStore(directory.resolve("values").toFile(),
				new LmdbStoreConfig())) {
			store.reconstructReferenceCountsOffline();
			assertTrue(store.hasTrustedReferenceCounts());
			assertFalse(store.isReferenceCountVerificationPending());
			assertEquals(shared, store.getValue(store.getId(shared)));
		}
		try (ClosingValueStore store = new ClosingValueStore(directory.resolve("values").toFile(),
				new LmdbStoreConfig())) {
			assertTrue(store.hasTrustedReferenceCounts());
		}
	}

