	@Test
	void trustedLegacyCloseRetainsPendingUnusedValuesAfterReaderManagerCloses() throws Exception {
		LmdbCompatibilityFixtures.extract("v2-610-default.zip", directory);
		// This case asserts the durable-policy foreground/post-ready maintenance boundary.
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc,ospc").setAsyncValueCleanup(false)
				.setLegacyReferenceCountRepairEnabled(true);
		LmdbStore.reconstructReferenceCountsOffline(directory.toFile(), config);
		LmdbStore sail = new LmdbStore(directory.toFile(), config);
		SailRepository repository = new SailRepository(sail);
		repository.init();
		assertTrue(sail.awaitIndexRebuild(20, TimeUnit.SECONDS));
		var vf = SimpleValueFactory.getInstance();
		var subject = vf.createIRI("urn:authority:close-subject");
		var predicate = vf.createIRI("urn:authority:close-predicate");
		var removed = vf.createLiteral("close preserves this deferred dictionary payload");
		var kept = vf.createLiteral("acknowledged surviving statement");
		ValueStore values = (ValueStore) sail.getValueFactory();
		long removedId;
		LmdbValue retained;
		try (var connection = repository.getConnection()) {
			connection.begin();
			connection.add(subject, predicate, removed);
			connection.add(subject, predicate, kept);
			connection.commit();
			removedId = values.getId(removed);
			retained = values.getLazyValue(removedId);
			connection.begin();
			connection.remove(subject, predicate, removed);
			connection.commit();
			assertTrue(values.hasTrustedReferenceCounts());
			assertTrue(values.getLmdbStats().get("unused_ids").entries() > 0L,
					"the close reproduction must retain a real pending-unused payload");
			assertTrue(connection.hasStatement(subject, predicate, kept, false));
		}
		assertDoesNotThrow(repository::shutDown,
				"normal shutdown cannot run a liveness callback through the already-closed TripleStore reader manager");
		Reference.reachabilityFence(retained);
		assertTrue(LmdbCompatibilityFixtures.nativeGet(directory, null,
				LmdbCompatibilityFixtures.idKey(removedId)) != null,
				"deferred maintenance retains the durable payload");
		repository = new SailRepository(new LmdbStore(directory.toFile(), config));
		repository.init();
		try (var connection = repository.getConnection()) {
			assertTrue(connection.hasStatement(subject, predicate, kept, false));
			assertFalse(connection.hasStatement(subject, predicate, removed, false));
		} finally {
			repository.shutDown();
		}
	}

	@ParameterizedTest
	@ValueSource(strings = { "self", "mutual", "dangling" })
	void reconstructionRejectsCyclicAndDanglingLiveTermOwners(String corruption) throws Exception {
		var vf = SimpleValueFactory.getInstance();
		StoreProperties properties = new StoreProperties(directory.toFile());
		var subject = vf.createIRI("urn:authority:graph-subject");
		var predicate = vf.createIRI("urn:authority:graph-predicate");
		var objectA = vf.createBNode("graph-object-a");
		var objectB = vf.createBNode("graph-object-b");
		long subjectId;
		long predicateId;
		long objectAId;
		long objectBId;
		long termA;
		long termB;
		LmdbStore owner = new LmdbStore(directory.toFile(), new LmdbStoreConfig());
		SailRepository repository = new SailRepository(owner);
		repository.init();
		try (var connection = repository.getConnection()) {
			var first = vf.createTripleTerm(subject, predicate, objectA);
			var second = vf.createTripleTerm(subject, predicate, objectB);
			connection.begin();
			connection.add(subject, predicate, first);
			connection.add(subject, predicate, second);
			connection.commit();
			ValueStore store = owner.getBackingStore().valueStore();
			termA = store.getId(first);
			termB = store.getId(second);
			subjectId = store.getId(subject);
			predicateId = store.getId(predicate);
			objectAId = store.getId(objectA);
			objectBId = store.getId(objectB);
		} finally {
			repository.shutDown();
		}
		properties.load();
		assertDoesNotThrow(() -> LmdbStore.verifyStoreOffline(directory.toFile(), new LmdbStoreConfig()),
				"the complete repository must pass read-only verification before graph corruption");
		long childA = corruption.equals("self") ? termA
				: corruption.equals("mutual") ? termB : ValueIds.createId(ValueIds.T_TRIPLE, 1_000_000L);
		for (String spec : Set.of("spoc", "cspo")) {
			String database = TripleIndex.nativeDatabaseName("term-" + spec, true);
			LmdbCompatibilityFixtures.nativePut(directory, database,
					TripleIndex.encodeKey(spec, subjectId, predicateId, objectAId, termA), null);
			LmdbCompatibilityFixtures.nativePut(directory, database,
					TripleIndex.encodeKey(spec, subjectId, predicateId, childA, termA), new byte[0]);
			if (corruption.equals("mutual")) {
				LmdbCompatibilityFixtures.nativePut(directory, database,
						TripleIndex.encodeKey(spec, subjectId, predicateId, objectBId, termB), null);
				LmdbCompatibilityFixtures.nativePut(directory, database,
						TripleIndex.encodeKey(spec, subjectId, predicateId, termA, termB), new byte[0]);
			}
		}
		try (ClosingValueStore store = new ClosingValueStore(directory.resolve("values").toFile(), properties,
				new LmdbStoreConfig())) {
			assertFalse(store.hasTrustedReferenceCounts());
			assertThrows(IOException.class, store::reconstructReferenceCountsOffline,
					"full owner-graph reconstruction cannot certify " + corruption + " term dependencies");
			assertFalse(store.hasTrustedReferenceCounts());
		}
		assertNull(LmdbCompatibilityFixtures.nativeGet(directory, "gc_meta", ReferenceCountProof.KEY));
		IOException failure = assertThrows(IOException.class,
				() -> LmdbStore.verifyStoreOffline(directory.toFile(), new LmdbStoreConfig()),
				"read-only explicit verification must reject " + corruption + " term dependencies too");
		if (!corruption.equals("dangling")) {
			assertTrue(failure.getMessage().contains("Cyclic"), failure.getMessage());
		}
	}

	@Test
	void reconstructionValidatesDeepSharedTermGraphsWithoutARecursiveJavaStack() throws Exception {
		var vf = SimpleValueFactory.getInstance();
		try (ClosingValueStore store = new ClosingValueStore(directory.resolve("values").toFile(),
				new LmdbStoreConfig())) {
			store.startTransaction(true);
			long subject = store.storeValue(vf.createIRI("urn:authority:deep-subject"));
			long predicate = store.storeValue(vf.createIRI("urn:authority:deep-predicate"));
			long leaf = store.storeValue(vf.createLiteral("shared deep leaf"));
			store.commit();
			List<long[]> terms = new ArrayList<>();
			int depth = 2050;
			for (int i = 0; i < depth; i++) {
				long owner = ValueIds.createId(ValueIds.T_TRIPLE, 1_000_000L + i);
				long child = i == depth - 1 ? leaf : ValueIds.createId(ValueIds.T_TRIPLE, 1_000_001L + i);
				terms.add(new long[] { subject, predicate, child, owner });
			}
			for (String spec : List.of("spoc", "cspo")) {
				terms.sort((left, right) -> Arrays.compareUnsigned(
						TripleIndex.encodeKey(spec, left[0], left[1], left[2], left[3]),
						TripleIndex.encodeKey(spec, right[0], right[1], right[2], right[3])));
				var iterator = terms.iterator();
				store.appendBulkTripleTermIndex(spec, tuple -> {
					if (!iterator.hasNext()) {
						return false;
					}
					long[] logical = iterator.next();
					for (int position = 0; position < 4; position++) {
						tuple[position] = logical["spoc".indexOf(spec.charAt(position))];
					}
					return true;
				}, 512);
			}
			assertFalse(store.hasTrustedReferenceCounts());
			store.reconstructReferenceCountsOffline();
			assertTrue(store.hasTrustedReferenceCounts());
		}
	}

	@ParameterizedTest
	@ValueSource(strings = { "noncanonical-spoc", "noncanonical-cspo", "literal-subject", "literal-predicate",
			"triple-predicate", "namespace-object" })
	void reconstructionRejectsNonCanonicalOrInvalidRoleTermOwners(String corruption) throws Exception {
		var vf = SimpleValueFactory.getInstance();
		long subject;
		long predicate;
		long literal;
		long owner;
		long otherTerm;
		try (ClosingValueStore store = new ClosingValueStore(directory.resolve("values").toFile(),
				new LmdbStoreConfig())) {
			store.startTransaction(true);
			var s = vf.createIRI("urn:authority:role-subject");
			var p = vf.createIRI("urn:authority:role-predicate");
			var o = vf.createLiteral("invalid RDF role probe");
			owner = store.storeValue(vf.createTripleTerm(s, p, o));
			otherTerm = store.storeValue(vf.createTripleTerm(vf.createBNode("role-other"), p, o));
			subject = store.getId(s);
			predicate = store.getId(p);
			literal = store.getId(o);
			store.commit();
		}
		if (corruption.startsWith("noncanonical")) {
			String spec = corruption.endsWith("spoc") ? "spoc" : "cspo";
			byte[] canonical = TripleIndex.encodeKey(spec, subject, predicate, literal, owner);
			ByteBuffer input = ByteBuffer.wrap(canonical);
			long first = Varint.readUnsigned(input);
			ByteBuffer noncanonical = ByteBuffer.allocate(9 + input.remaining());
			noncanonical.put((byte) 255).putLong(first).put(input);
			String database = TripleIndex.nativeDatabaseName("term-" + spec, true);
			if (spec.equals("cspo")) {
				LmdbCompatibilityFixtures.nativePut(directory, database, canonical, null);
			}
			LmdbCompatibilityFixtures.nativePut(directory, database, noncanonical.array(), new byte[0]);
		} else {
			long changedSubject = corruption.equals("literal-subject") ? literal : subject;
			long changedPredicate = corruption.equals("literal-predicate") ? literal
					: corruption.equals("triple-predicate") ? otherTerm : predicate;
			byte[] subjectRecord = LmdbCompatibilityFixtures.nativeGet(directory, null,
					ValueStoreRecordCodec.idKey(subject));
			long namespace = Varint.readUnsigned(ByteBuffer.wrap(subjectRecord, 1, subjectRecord.length - 1));
			long changedObject = corruption.equals("namespace-object") ? namespace : literal;
			for (String spec : Set.of("spoc", "cspo")) {
				String database = TripleIndex.nativeDatabaseName("term-" + spec, true);
				LmdbCompatibilityFixtures.nativePut(directory, database,
						TripleIndex.encodeKey(spec, subject, predicate, literal, owner), null);
				LmdbCompatibilityFixtures.nativePut(directory, database,
						TripleIndex.encodeKey(spec, changedSubject, changedPredicate, changedObject, owner),
						new byte[0]);
			}
		}
		assertThrows(IOException.class, () -> {
			try (ClosingValueStore store = new ClosingValueStore(directory.resolve("values").toFile(),
					new LmdbStoreConfig())) {
				assertFalse(store.hasTrustedReferenceCounts());
				store.reconstructReferenceCountsOffline();
			}
		}, "full reconstruction must reject malformed owner authority: " + corruption);
		byte[] proof = LmdbCompatibilityFixtures.nativeGet(directory, "gc_meta", ReferenceCountProof.KEY);
		if (proof != null) {
			byte[] generation = LmdbCompatibilityFixtures.nativeGet(directory, "gc_meta",
					ReferenceCountProof.GENERATION_KEY);
			assertEquals(-1L, ReferenceCountProof.trustedNextId(ByteBuffer.wrap(proof), generation,
					LmdbCompatibilityFixtures.nativeTransactionId(directory)),
					"a rejected startup may retain stale bytes but cannot publish matching exact authority");
		}
	}

	@Test
	void missingAllocationAuthorityDoesNotIgnoreCspoExtremumReadFailure() throws Exception {
		var vf = SimpleValueFactory.getInstance();
		try (ClosingValueStore store = new ClosingValueStore(directory.resolve("values").toFile(),
				new LmdbStoreConfig())) {
			store.startTransaction(true);
			store.storeValue(vf.createTripleTerm(vf.createIRI("urn:authority:last-subject"),
					vf.createIRI("urn:authority:last-predicate"), vf.createBNode("last-object")));
			store.commit();
		}
		LmdbCompatibilityFixtures.nativePut(directory, "gc_meta", ReferenceCountProof.KEY, null);
		LmdbCompatibilityFixtures.nativePut(directory, "gc_meta", ReferenceCountProof.ALLOCATION_KEY, null);
		long before = LmdbCompatibilityFixtures.nativeTransactionId(directory);
		AtomicInteger cspo = new AtomicInteger(-1);
		AtomicLong cursor = new AtomicLong();
		try (MockedStatic<LMDB> ignored = mockStatic(LMDB.class, invocation -> {
			String method = invocation.getMethod().getName();
			if (method.equals("mdb_dbi_open")
					&& "term-cspoterm-cspo".equals(invocation.getArgument(1))) {
				Object result = invocation.callRealMethod();
				if (((Integer) result) == LMDB.MDB_SUCCESS) {
					IntBuffer handle = invocation.getArgument(3);
					cspo.set(handle.get(handle.position()));
				}
				return result;
			}
			if (method.equals("mdb_cursor_open") && ((Integer) invocation.getArgument(1)) == cspo.get()) {
				Object result = invocation.callRealMethod();
				PointerBuffer handle = invocation.getArgument(2);
				cursor.set(handle.get(handle.position()));
				return result;
			}
			if (method.equals("mdb_cursor_get") && ((Long) invocation.getArgument(0)) == cursor.get()
					&& ((Integer) invocation.getArgument(3)) == LMDB.MDB_LAST) {
				return LMDB.MDB_CORRUPTED;
			}
			return invocation.callRealMethod();
		})) {
			assertThrows(IOException.class, () -> {
				try (ClosingValueStore store = new ClosingValueStore(directory.resolve("values").toFile(),
						new LmdbStoreConfig())) {
					// Failed native extrema cannot authorize a writable allocation high-water mark.
				}
			});
		}
		assertEquals(before, LmdbCompatibilityFixtures.nativeTransactionId(directory));
	}

